// GhostGuard voice approval — tests.
//
// The "voice" in every test is a SYNTHETIC fixture: a minimal WAV file
// generated byte-by-byte below (header + a few PCM samples). It is not
// a recording of any person, it contains no speech, and nothing in
// this suite transcribes or identifies anything — the code under test
// treats audio as opaque bytes, which is exactly what is proven here.
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { createHash } from "node:crypto";
import { appendFileSync, existsSync, mkdtempSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { decideWithVoice, listPending, readDecisions, verifyEvidence } from "../src/voice-decide.mjs";
import { hashValue } from "../src/hash.mjs";

const here = dirname(fileURLToPath(import.meta.url));
const cli = join(here, "..", "src", "cli.mjs");

let passed = 0;
function check(name, fn) {
  fn();
  passed++;
  process.stdout.write(`  ✓ ${name}\n`);
}
function throwsWith(fn, needle) {
  try {
    fn();
  } catch (err) {
    assert.ok(err.message.includes(needle), `error "${err.message}" should mention "${needle}"`);
    return;
  }
  assert.fail(`expected an error mentioning "${needle}"`);
}
const sha256 = (buf) => createHash("sha256").update(buf).digest("hex");

/** A tiny SYNTHETIC wav: valid RIFF header + 8 silent PCM samples. Not speech. */
function syntheticWav() {
  const data = Buffer.alloc(16, 0);
  const buf = Buffer.alloc(44 + data.length);
  buf.write("RIFF", 0); buf.writeUInt32LE(36 + data.length, 4); buf.write("WAVE", 8);
  buf.write("fmt ", 12); buf.writeUInt32LE(16, 16); buf.writeUInt16LE(1, 20); buf.writeUInt16LE(1, 22);
  buf.writeUInt32LE(8000, 24); buf.writeUInt32LE(16000, 28); buf.writeUInt16LE(2, 32); buf.writeUInt16LE(16, 34);
  buf.write("data", 36); buf.writeUInt32LE(data.length, 40);
  data.copy(buf, 44);
  return buf;
}

function record(over) {
  return {
    action_id: "x", kind: "mcp.tools/call", permission_class: "COMMUNICATE",
    actor: "agent-1", initiator: "person", project_id: "proj-1",
    verdict: "ask", rule_id: "comms-ask", reason: "comms need a human",
    handoff_to: null, target_ref: null, snapshot_id: null, target: null,
    action_payload: { tool: "send_email", arguments: { to: "a@example.com", body: "hi" } },
    dry_run: false, ...over,
  };
}

function setup() {
  const dir = mkdtempSync(join(tmpdir(), "gg-voice-"));
  const trail = join(dir, "trail.jsonl");
  const records = [
    record({ action_id: "ask-1" }),
    record({ action_id: "handoff-1", verdict: "hand_off", rule_id: "comms-handoff", handoff_to: "owner", permission_class: "PUBLISH",
             action_payload: { tool: "publish_post", arguments: { text: "hello" } } }),
    record({ action_id: "deny-1", verdict: "deny", rule_id: "no-spend-ever", permission_class: "SPEND",
             action_payload: { tool: "buy", arguments: { item: "gift card", amount: 50 } } }),
    record({ action_id: "allow-1", verdict: "allow", rule_id: "reads-allow", permission_class: "READ",
             action_payload: { tool: "echo", arguments: { text: "hi" } } }),
  ];
  writeFileSync(trail, records.map((r) => JSON.stringify(r)).join("\n") + "\n");
  const audio = join(dir, "voice-note.wav");
  writeFileSync(audio, syntheticWav());
  return { dir, trail, decisions: join(dir, "decisions.jsonl"), evidence: join(dir, "evidence"), audio,
           opts: null };
}
function baseOpts(s, over = {}) {
  return { trailPath: s.trail, decisionsPath: s.decisions, evidenceDir: s.evidence,
           actionId: "ask-1", audioPath: s.audio, decision: "approve", approver: "Ryan",
           decidedAt: "2026-10-10T05:00:00.000Z", ...over };
}

// 1. Approve flow — hash-bound decision entry appended.
{
  const s = setup();
  const trailHashBefore = sha256(readFileSync(s.trail));
  const entry = decideWithVoice(baseOpts(s));
  check("approve appends a decision entry with the Cloud decision shape + voice fields", () => {
    assert.equal(entry.entry_type, "decision");
    assert.equal(entry.channel, "voice");
    assert.equal(entry.action_id, "ask-1");
    assert.equal(entry.project_id, "proj-1");
    assert.equal(entry.decision, "approve");
    assert.equal(entry.approver, "Ryan");
    assert.equal(entry.decided_at, "2026-10-10T05:00:00.000Z");
    assert.equal(entry.verdict_answered, "ask");
  });
  check("entry is bound to the ask's exact payload hash", () => {
    const ask = JSON.parse(readFileSync(s.trail, "utf8").split("\n")[0]);
    assert.equal(entry.payload_sha256, hashValue(ask.action_payload));
  });
  check("audio_sha256 is the hash of the recording bytes; evidence copy is byte-identical", () => {
    const original = readFileSync(s.audio);
    assert.equal(entry.audio_sha256, sha256(original));
    assert.equal(entry.audio_bytes, original.length);
    const stored = readFileSync(join(s.evidence, entry.audio_file));
    assert.ok(stored.equals(original), "evidence must be a verbatim copy");
  });
  check("the trail file itself was not modified (decisions live in their own append-only file)", () => {
    assert.equal(sha256(readFileSync(s.trail)), trailHashBefore);
  });
}

// 2. Deny flow on a hand_off record.
{
  const s = setup();
  const entry = decideWithVoice(baseOpts(s, { actionId: "handoff-1", decision: "deny" }));
  check("deny decision on a hand_off record is recorded as a deny", () => {
    assert.equal(entry.decision, "deny");
    assert.equal(entry.verdict_answered, "hand_off");
    assert.equal(readDecisions(s.decisions).length, 1);
  });
}

// 3. Unknown action errors, nothing written.
{
  const s = setup();
  check("unknown action_id errors and writes nothing", () => {
    throwsWith(() => decideWithVoice(baseOpts(s, { actionId: "nope-9" })), "unknown action_id");
    assert.equal(readDecisions(s.decisions).length, 0);
    assert.ok(!existsSync(s.evidence) || readdirSync(s.evidence).length === 0);
  });
}

// 4. Double decision errors; file unchanged.
{
  const s = setup();
  decideWithVoice(baseOpts(s));
  check("deciding an already-decided action errors; decisions file unchanged", () => {
    const before = readFileSync(s.decisions, "utf8");
    throwsWith(() => decideWithVoice(baseOpts(s, { decision: "deny" })), "already decided");
    assert.equal(readFileSync(s.decisions, "utf8"), before);
    assert.equal(readDecisions(s.decisions).length, 1);
  });
}

// 5. Voice cannot override a policy deny (or an allow — only ask/hand_off are decidable).
{
  const s = setup();
  check("voice-approving a deny-verdict action errors — voice never overrides policy", () => {
    throwsWith(() => decideWithVoice(baseOpts(s, { actionId: "deny-1" })), 'verdict "deny"');
    assert.equal(readDecisions(s.decisions).length, 0);
  });
  check("an allow-verdict action is not decidable either", () => {
    throwsWith(() => decideWithVoice(baseOpts(s, { actionId: "allow-1" })), 'verdict "allow"');
  });
}

// 6. Tamper detection: verify passes, then evidence is altered, verify reports it.
{
  const s = setup();
  const entry = decideWithVoice(baseOpts(s));
  check("verify passes on untouched evidence", () => {
    const r = verifyEvidence(s.decisions, s.evidence);
    assert.equal(r.ok, true);
    assert.equal(r.checked, 1);
  });
  check("tampering with the stored recording afterwards is detected by verify", () => {
    appendFileSync(join(s.evidence, entry.audio_file), Buffer.from([0x41]));
    const r = verifyEvidence(s.decisions, s.evidence);
    assert.equal(r.ok, false);
    assert.equal(r.mismatches.length, 1);
    assert.equal(r.mismatches[0].action_id, "ask-1");
    assert.match(r.mismatches[0].problem, /mismatch/);
  });
  check("CLI verify exits 1 and names the mismatch after tampering", () => {
    const res = spawnSync("node", [cli, "verify", "--decisions", s.decisions, "--evidence", s.evidence], { encoding: "utf8" });
    assert.equal(res.status, 1);
    assert.match(res.stdout, /MISMATCH ask-1/);
  });
}

// 7. CLI decide smoke + pending list shrinks.
{
  const s = setup();
  check("CLI decide records an approval end-to-end; pending no longer lists it", () => {
    const res = spawnSync("node", [cli, "decide", "--trail", s.trail, "--decisions", s.decisions,
      "--evidence", s.evidence, "--action", "ask-1", "--audio", s.audio,
      "--decision", "approve", "--approver", "Ryan"], { encoding: "utf8" });
    assert.equal(res.status, 0, res.stderr);
    assert.equal(readDecisions(s.decisions).length, 1);
    const pendingIds = listPending(s.trail, s.decisions).map((r) => r.action_id);
    assert.deepEqual(pendingIds, ["handoff-1"]);
  });
}

// 8. Trail is read-only for decide: bytes identical before/after.
{
  const s = setup();
  const before = sha256(readFileSync(s.trail));
  decideWithVoice(baseOpts(s));
  check("decide never rewrites the trail (append-only history stays intact)", () => {
    assert.equal(sha256(readFileSync(s.trail)), before);
  });
}

process.stdout.write(`\nghostguard-voice: ${passed} passed, 0 failed\n`);
